#include <atomic>
#include <type_traits>
#include <cassert>
#include <iostream>

int main() {
    static_assert(!std::is_copy_assignable<std::atomic_flag>::value,
        "Atomic flags cannot be copy-assigned");
    std::atomic_flag flag = ATOMIC_FLAG_INIT;
    assert(!flag.test_and_set());
    flag.clear();
    std::cout << "Checks passed\n";
}
